use vstd::prelude::*;

verus! {
    fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> (result: Vec<T>)
        requires
            dst.len() == src.len() && src.len() == mask.len(),
            dst.len() > 0, // Assuming non-empty arrays
        ensures
            result.len() == dst.len(),
            forall(|i: nat| i < dst.len() as nat ==> (mask[i as usize] ==> result[i as usize] == src[i as usize]) && (!mask[i as usize] ==> result[i as usize] == dst[i as usize])),
    {
        let mut result: Vec<T> = Vec::new();
        let len = dst.len();

        // Initialize the result vector with the same length
        result.resize(len, dst[0]); // Default value, will be overwritten

        let mut i: usize = 0;
        while i < len
            invariant
                i <= len,
                result.len() == len,
                forall(|j: nat| j < i as nat ==> (mask[j as usize] ==> result[j as usize] == src[j as usize]) && (!mask[j as usize] ==> result[j as usize] == dst[j as usize])),
            decreases len - i,
        {
            if mask[i] {
                result[i] = src[i];
            } else {
                result[i] = dst[i];
            }
            i = i + 1;
        }
        result
    }
}
